const statusHistory = `-- name: StatusHistory :many
SELECT from_status, to_status, actor_type, actor_id, reason, changed_at
FROM identity.user_status_history WHERE user_id = $1 ORDER BY id
`

type StatusHistoryRow struct {
	FromStatus *string
	ToStatus   string
	ActorType  *string
	ActorID    *string
	Reason     *string
	ChangedAt  time.Time
}

// An account's status changes, oldest first.
func (q *Queries) StatusHistory(ctx context.Context, userID string) ([]StatusHistoryRow, error) {
	rows, err := q.db.Query(ctx, statusHistory, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StatusHistoryRow
	for rows.Next() {
		var i StatusHistoryRow
		if err := rows.Scan(
			&i.FromStatus,
			&i.ToStatus,
			&i.ActorType,
			&i.ActorID,
			&i.Reason,
			&i.ChangedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertDevice = `-- name: UpsertDevice :one
INSERT INTO identity.devices (user_id, fingerprint_hash, platform, attestation_verdict, first_seen_at, last_seen_at)
VALUES ($1, $2, $3, $4, $5, $5)
ON CONFLICT (user_id, fingerprint_hash) DO UPDATE
   SET last_seen_at = EXCLUDED.last_seen_at, attestation_verdict = EXCLUDED.attestation_verdict
RETURNING id
`

type UpsertDeviceParams struct {
	UserID             string
	FingerprintHash    []byte
	Platform           string
	AttestationVerdict string
	At                 time.Time
}

func (q *Queries) UpsertDevice(ctx context.Context, arg UpsertDeviceParams) (string, error) {
	row := q.db.QueryRow(ctx, upsertDevice,
		arg.UserID,
		arg.FingerprintHash,
		arg.Platform,
		arg.AttestationVerdict,
		arg.At,
	)
	var id string
	err := row.Scan(&id)
	return id, err
}

